/**
 * @param {Object|Array} obj
 * @return {Object|Array} immutable
 */
var makeImmutable = function(obj) {
    const arrayMutators = new Set(['pop', 'push', 'shift', 'unshift', 'splice', 'sort', 'reverse']);
    const cache = new WeakMap();   // keeps obj.a === obj.a (same proxy each time)

    const wrap = (target) => {
        if (cache.has(target)) return cache.get(target);
        const isArr = Array.isArray(target);
        const fail = (prop) => {
            // throw string literals, not Error objects
            throw isArr ? `Error Modifying Index: ${String(prop)}`
                        : `Error Modifying: ${String(prop)}`;
        };
        const proxy = new Proxy(target, {
            get(t, prop) {
                if (isArr && arrayMutators.has(prop)) {
                    return () => { throw `Error Calling Method: ${prop}`; };
                }
                const value = t[prop];
                // lazily wrap nested objects/arrays for deep immutability
                return (value !== null && typeof value === 'object') ? wrap(value) : value;
            },
            set(t, prop) { fail(prop); },
            deleteProperty(t, prop) { fail(prop); },
            defineProperty(t, prop) { fail(prop); }
        });
        cache.set(target, proxy);
        return proxy;
    };

    return wrap(obj);
};

/**
 * const obj = makeImmutable({x: 5});
 * obj.x = 6; // throws "Error Modifying: x"
 */
